@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/D96A-INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "D96A INVOIC Profound Ontology" ;
    rdfs:comment "A deeply structured OWL2 ontology for the UN/EDIFACT D96A INVOIC message, with full segment, role, and compliance representation as required by EN 16931-1 and P2P-O." .

### CLASSES

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope of an EDIFACT transmission, containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message for global trade transactions, as per D96A." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:DTMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment for document and line dates." .

:MOASegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment for invoice and line totals." .

:QTYSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment for item and line quantities." .

:LINSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line Item segment for itemized details." .

:PIASegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PIA Segment" ;
    rdfs:comment "Additional Product ID segment for product identification." .

:TAXSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax segment for tax breakdowns." .

:ALCSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowances/Charges segment." .

:UNSSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNS Segment" ;
    rdfs:comment "Section control segment for message section delimitation." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:MessageHeader a owl:Class ;
    rdfs:label "Message Header" ;
    rdfs:comment "The header section of an invoice message." .

:MessageDetail a owl:Class ;
    rdfs:label "Message Detail" ;
    rdfs:comment "The detail section listing line items." .

:MessageSummary a owl:Class ;
    rdfs:label "Message Summary" ;
    rdfs:comment "The summary section with totals and taxes." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business party involved in the invoice, such as buyer or supplier." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the message context." .

:BuyerRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in the invoice." .

:DeliveryPartyRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in the invoice." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Postal or physical address of an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "The price of an item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax details for the invoice or item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "Reference number for invoice or document." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Total amount of the invoice." .

:InvoiceNumber a owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "Number identifying the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "The business process to which the invoice is assigned." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations or items." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN identifier for organizations." .

:EN16931Conformance a owl:Class ;
    rdfs:label "EN 16931 Conformance" ;
    rdfs:comment "Indicates conformance to the European Standard EN 16931-1." .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Indicates alignment with the Purchase-to-Pay Ontology." .

:SHACLConstraint a owl:Class ;
    rdfs:label "SHACL Constraint" ;
    rdfs:comment "A SHACL constraint for automated validation." .

:Pivot_OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class to reify the assignment of a role to an organization in a message context." .

### OBJECT PROPERTIES

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to a message." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a message to its segments." .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MessageHeader ;
    rdfs:label "has header" ;
    rdfs:comment "Links an invoice message to its header section." .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MessageDetail ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an invoice message to its detail section." .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MessageSummary ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an invoice message to its summary section." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to simple data elements." .

:playedBy a owl:ObjectProperty , owl:InverseFunctionalProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :Organization ;
    rdfs:label "played by" ;
    rdfs:comment "Links an agent role to the organization playing it." .

:assignedRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "assigned role" ;
    rdfs:comment "Assigns a specific role to an organization in a message context." .

:assignedOrganization a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "assigned organization" ;
    rdfs:comment "Assigns a specific organization to a role in a message context." .

:inMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Pivot_OrganizationRoleAssignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "in message" ;
    rdfs:comment "Contextualizes the organization-role assignment within a message." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its address." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an organization to its identifiers." .

:hasGlobalLocationNumber a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has global location number" ;
    rdfs:comment "Links an organization to its GLN." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :MessageDetail ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Links message detail to items." .

:hasLineSegment a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :LINSegment ;
    rdfs:label "has line segment" ;
    rdfs:comment "Links an item to its LIN segment." .

:hasPIASegment a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :PIASegment ;
    rdfs:label "has PIA segment" ;
    rdfs:comment "Links an item to its PIA segment for product identification." .

:hasQTYSegment a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :QTYSegment ;
    rdfs:label "has QTY segment" ;
    rdfs:comment "Links an item to its QTY segment for quantities." .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range :Price ;
    rdfs:label "has price" ;
    rdfs:comment "Links an item to its price." .

:hasMOASegment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :MOASegment ;
    rdfs:label "has MOA segment" ;
    rdfs:comment "Links invoice message to monetary amount segments." .

:hasDTMSegment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :DTMSegment ;
    rdfs:label "has DTM segment" ;
    rdfs:comment "Links invoice message to DTM segments for dates." .

:hasTaxSegment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :TAXSegment ;
    rdfs:label "has TAX segment" ;
    rdfs:comment "Links invoice message to tax segments." .

:hasALCSegment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ALCSegment ;
    rdfs:label "has ALC segment" ;
    rdfs:comment "Links invoice message to allowance/charge segments." .

:hasUNSSegment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :UNSSegment ;
    rdfs:label "has UNS segment" ;
    rdfs:comment "Links invoice message to section control segments." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links an invoice message to its tax information." .

:hasReferenceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceNumber ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links an invoice message to its reference number." .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceAmount ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links an invoice message to its invoice amount." .

:hasInvoiceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceNumber ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Links an invoice message to its invoice number." .

:conformsToEN16931 a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :EN16931Conformance ;
    rdfs:label "conforms to EN 16931-1" ;
    rdfs:comment "Indicates if the invoice message conforms to EN 16931-1." .

:alignsWithP2PO a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2POAlignment ;
    rdfs:label "aligns with P2P-O" ;
    rdfs:comment "Indicates alignment with the Purchase-to-Pay Ontology." .

:validatedBySHACL a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :SHACLConstraint ;
    rdfs:label "validated by SHACL" ;
    rdfs:comment "Indicates validation by SHACL constraints." .

:hasBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    rdfs:label "has business process" ;
    rdfs:comment "Links an invoice message to a business process." .

### DATA PROPERTIES

:elementValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range xsd:string ;
    rdfs:label "element value" ;
    rdfs:comment "The value of a simple data element." .

:postalCode a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "Postal code of an address." .

:city a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "City of an address." .

:street a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "street" ;
    rdfs:comment "Street of an address." .

:countryCode a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country code" ;
    rdfs:comment "Country code of an address." .

:identifierValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "identifier value" ;
    rdfs:comment "The value of an identifier." .

:glnValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    rdfs:label "GLN value" ;
    rdfs:comment "The value of a global location number." .

:itemDescription a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "item description" ;
    rdfs:comment "Description of an item." .

:itemQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:decimal ;
    rdfs:label "item quantity" ;
    rdfs:comment "Quantity of an item." .

:netPriceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "net price amount" ;
    rdfs:comment "Net price amount of an item." .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "Tax amount for the invoice." .

:referenceNumberValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "reference number value" ;
    rdfs:comment "Reference number value." .

:invoiceAmountValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount value" ;
    rdfs:comment "Total amount of the invoice." .

:invoiceNumberValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number value" ;
    rdfs:comment "Invoice number value." .

### CLASS AXIOMS & RESTRICTIONS

:BuyerRole owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playedBy ; owl:someValuesFrom :Organization ] .

:Pivot_OrganizationRoleAssignment owl:equivalentClass [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:someValuesFrom :AgentRole ] ,
    [ a owl:Restriction ; owl:onProperty :assignedOrganization ; owl:someValuesFrom :Organization ] ,
    [ a owl:Restriction ; owl:onProperty :inMessage ; owl:someValuesFrom :InvoiceMessage ] .

:InvoiceMessage owl:equivalentClass [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:someValuesFrom :MessageHeader ] ,
    [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:someValuesFrom :MessageDetail ] ,
    [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:someValuesFrom :MessageSummary ] .

:Item owl:equivalentClass [ a owl:Restriction ; owl:onProperty :hasLineSegment ; owl:someValuesFrom :LINSegment ] ,
    [ a owl:Restriction ; owl:onProperty :hasPIASegment ; owl:someValuesFrom :PIASegment ] ,
    [ a owl:Restriction ; owl:onProperty :hasQTYSegment ; owl:someValuesFrom :QTYSegment ] .

### DISJOINTNESS

:MessageHeader owl:disjointWith :MessageDetail , :MessageSummary .
:MessageDetail owl:disjointWith :MessageSummary .
:BuyerRole owl:disjointWith :DeliveryPartyRole .
:BGMSegment owl:disjointWith :NADSegment , :DTMSegment , :MOASegment , :QTYSegment , :LINSegment , :PIASegment , :TAXSegment , :ALCSegment , :UNSSegment .

### ANNOTATIONS
# (Annotations are included above for all classes and properties)

