@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/D96A-INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "D96A INVOIC Profound Ontology" ;
    rdfs:comment "A deeply structured OWL2 ontology for the UN/EDIFACT D96A INVOIC message, with full segment, role, and compliance representation as required by EN 16931-1 and P2P-O." .

### CLASSES

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope of an EDIFACT transmission, containing one or more messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An INVOIC message for global trade transactions, as per D96A." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A generic EDIFACT segment." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." .

:DTMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment for document and line dates." .

:MOASegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment for invoice and line totals." .

:QTYSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment for item and line quantities." .

:LINSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line Item segment for itemized details." .

:PIASegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "PIA Segment" ;
    rdfs:comment "Additional Product ID segment for product identification." .

:TAXSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax segment for tax breakdowns." .

:ALCSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "ALC Segment" ;
    rdfs:comment "Allowances/Charges segment." .

:UNSSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "UNS Segment" ;
    rdfs:comment "Section control segment for message section delimitation." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:MessageHeader a owl:Class ;
    rdfs:label "Message Header" ;
    rdfs:comment "The header section of an invoice message." .

:MessageDetail a owl:Class ;
    rdfs:label "Message Detail" ;
    rdfs:comment "The detail section listing line items." .

:MessageSummary a owl:Class ;
    rdfs:label "Message Summary" ;
    rdfs:comment "The summary section with totals and taxes." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business party involved in the invoice, such as buyer or supplier." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the message context." .

:BuyerRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in the invoice." .

:DeliveryPartyRole a owl:Class ;
    rdfs:subClassOf :AgentRole ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in the invoice." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "Postal or physical address of an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "The price of an item." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax details for the invoice or item." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "Reference number for invoice or document." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "Total amount of the invoice." .

:InvoiceNumber a owl:Class ;
    rdfs:label "Invoice Number" ;
    rdfs:comment "Number identifying the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "The business process to which the invoice is assigned." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations or items." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "GLN identifier for organizations." .

:EN16931Conformance a owl:Class ;
    rdfs:label "EN 16931 Conformance" ;
    rdfs:comment "Indicates conformance to the European Standard EN 16931-1." .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Indicates alignment with the Purchase-to-Pay Ontology." .

:SHACLConstraint a owl:Class ;
    rdfs:label "SHACL Constraint" ;
    rdfs:comment "A SHACL constraint for automated validation." .

:PivotOrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class to reify the assignment of a role to an organization in a message context." .

### OBJECT PROPERTIES

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to a message." ;
    owl:inverseOf :isContainedByMessage .

