    rdfs:range :MessageSummary ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an invoice message to its summary section." ;
    owl:inverseOf :isSummaryOfInvoiceMessage .

:isSummaryOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :MessageSummary ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is summary of invoice message" ;
    rdfs:comment "Inverse property for hasSummary." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a segment to its composite data elements." ;
    owl:inverseOf :isCompositeElementOfSegment .

:isCompositeElementOfSegment a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    rdfs:label "is composite element of segment" ;
    rdfs:comment "Inverse property for hasCompositeElement." .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a composite data element to simple data elements." ;
    owl:inverseOf :isSimpleElementOfComposite .

:isSimpleElementOfComposite a owl:ObjectProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "is simple element of composite" ;
    rdfs:comment "Inverse property for hasSimpleElement." .

:playedBy a owl:ObjectProperty , owl:InverseFunctionalProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :Organization ;
    rdfs:label "played by" ;
    rdfs:comment "Links an agent role to the organization playing it." ;
    owl:inverseOf :playsRole .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :AgentRole ;
    rdfs:label "plays role" ;
