:hasALCSegment a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ALCSegment ;
    rdfs:label "has ALC segment" ;
    rdfs:comment "Links invoice message to allowance/charge segments." ;
    owl:inverseOf :isALCSegmentOfInvoiceMessage .

:isALCSegmentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ALCSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is ALC segment of invoice message" ;
    rdfs:comment "Inverse property for hasALCSegment." .

:hasUNSSegment a owl:ObjectProperty ;
