    owl:inverseOf :isUNSSegmentOfInvoiceMessage .

:isUNSSegmentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :UNSSegment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is UNS segment of invoice message" ;
    rdfs:comment "Inverse property for hasUNSSegment." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
