    owl:inverseOf :isTaxOfInvoiceMessage .

:isTaxOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is tax of invoice message" ;
    rdfs:comment "Inverse property for hasTax." .

:hasReferenceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ReferenceNumber ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links an invoice message to its reference number." ;
    owl:inverseOf :isReferenceNumberOfInvoiceMessage .

:isReferenceNumberOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is reference number of invoice message" ;
    rdfs:comment "Inverse property for hasReferenceNumber." .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceAmount ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links an invoice message to its invoice amount." ;
    owl:inverseOf :isInvoiceAmountOfInvoiceMessage .

:isInvoiceAmountOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is invoice amount of invoice message" ;
    rdfs:comment "Inverse property for hasInvoiceAmount." .

:hasInvoiceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceNumber ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Links an invoice message to its invoice number." ;
    owl:inverseOf :isInvoiceNumberOfInvoiceMessage .

:isInvoiceNumberOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :InvoiceNumber ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is invoice number of invoice message" ;
