    owl:inverseOf :isP2POAlignmentOfInvoiceMessage .

:isP2POAlignmentOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :P2POAlignment ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is P2PO alignment of invoice message" ;
    rdfs:comment "Inverse property for alignsWithP2PO." .

:validatedBySHACL a owl:ObjectProperty ;
