    rdfs:label "validated by SHACL" ;
    rdfs:comment "Indicates validation by SHACL constraints." ;
    owl:inverseOf :isSHACLConstraintOfInvoiceMessage .

:isSHACLConstraintOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :SHACLConstraint ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is SHACL constraint of invoice message" ;
    rdfs:comment "Inverse property for validatedBySHACL." .

:hasBusinessProcess a owl:ObjectProperty ;
