:isBusinessProcessOfInvoiceMessage a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    rdfs:label "is business process of invoice message" ;
    rdfs:comment "Inverse property for hasBusinessProcess." .

### DATA PROPERTIES

:elementValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range xsd:string ;
    rdfs:label "element value" ;
    rdfs:comment "The value of a simple data element." .

:postalCode a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "postal code" ;
    rdfs:comment "Postal code of an address." .

:city a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "city" ;
    rdfs:comment "City of an address." .

:street a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "street" ;
    rdfs:comment "Street of an address." .

:countryCode a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Address ;
    rdfs:range xsd:string ;
    rdfs:label "country code" ;
    rdfs:comment "Country code of an address." .

:identifierValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    rdfs:label "identifier value" ;
    rdfs:comment "The value of an identifier." .

:glnValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string ;
    rdfs:label "GLN value" ;
    rdfs:comment "The value of a global location number." .

:itemDescription a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:string ;
    rdfs:label "item description" ;
    rdfs:comment "Description of an item." .

:itemQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Item ;
    rdfs:range xsd:decimal ;
    rdfs:label "item quantity" ;
    rdfs:comment "Quantity of an item." .

:netPriceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal ;
    rdfs:label "net price amount" ;
    rdfs:comment "Net price amount of an item." .

:taxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal ;
    rdfs:label "tax amount" ;
    rdfs:comment "Tax amount for the invoice." .

:referenceNumberValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "reference number value" ;
    rdfs:comment "Reference number value." .

:invoiceAmountValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:decimal ;
    rdfs:label "invoice amount value" ;
    rdfs:comment "Total amount of the invoice." .

:invoiceNumberValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain :InvoiceNumber ;
    rdfs:range xsd:string ;
    rdfs:label "invoice number value" ;
    rdfs:comment "Invoice number value." .

### CLASS AXIOMS & RESTRICTIONS

:BuyerRole owl:equivalentClass [ a owl:Restriction ; owl:onProperty :playedBy ; owl:someValuesFrom :Organization ] .

:PivotOrganizationRoleAssignment owl:equivalentClass [ a owl:Restriction ; owl:onProperty :assignedRole ; owl:someValuesFrom :AgentRole ] ,
    [ a owl:Restriction ; owl:onProperty :assignedOrganization ; owl:someValuesFrom :Organization ] ,
    [ a owl:Restriction ; owl:onProperty :inMessage ; owl:someValuesFrom :InvoiceMessage ] .

:InvoiceMessage owl:equivalentClass [ a owl:Restriction ; owl:onProperty :hasHeader ; owl:someValuesFrom :MessageHeader ] ,
    [ a owl:Restriction ; owl:onProperty :hasDetail ; owl:someValuesFrom :MessageDetail ] ,
    [ a owl:Restriction ; owl:onProperty :hasSummary ; owl:someValuesFrom :MessageSummary ] .

:Item owl:equivalentClass [ a owl:Restriction ; owl:onProperty :hasLineSegment ; owl:someValuesFrom :LINSegment ] ,
    [ a owl:Restriction ; owl:onProperty :hasPIASegment ; owl:someValuesFrom :PIASegment ] ,
    [ a owl:Restriction ; owl:onProperty :hasQTYSegment ; owl:someValuesFrom :QTYSegment ] .

### DISJOINTNESS

:MessageHeader owl:disjointWith :MessageDetail , :MessageSummary .
:MessageDetail owl:disjointWith :MessageSummary .
:BuyerRole owl:disjointWith :DeliveryPartyRole .
:BGMSegment owl:disjointWith :NADSegment , :DTMSegment , :MOASegment , :QTYSegment , :LINSegment , :PIASegment , :TAXSegment , :ALCSegment , :UNSSegment .

### ANNOTATIONS
# (Annotations are included above for all classes and properties)
"}

